//! Rust model of `com.xj.common.router.CommonRouterTable`.
//!
//! The Java class is an empty Kotlin singleton; the real content is the set of
//! `@Route` constants generated by TheRouter's APT into the eight
//! `RouterMap__TheRouter__*.java` files. This module captures those exact
//! `(path, className)` pairs as a static table and offers a helper to build a
//! populated [`RouteTable`] from them.

use super::{Route, RouteTable};

/// APT version stamped into every generated router/service file.
pub const THEROUTER_APT_VERSION: &str = "1.3.0-rc4";

/// A static route definition: a path pattern and its target class name.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RouteDef {
    pub path: &'static str,
    pub target: &'static str,
}

