/// Build a populated route table from the static [`ROUTES`] definitions.
pub fn build_route_table() -> RouteTable {
    let mut table = RouteTable::new();
    table.register_all(ROUTES.iter().map(|def| Route::new(def.path, def.target)));
    table
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn static_table_has_all_routes() {
        assert_eq!(ROUTES.len(), 35);
        let table = build_route_table();
        assert_eq!(table.len(), 35);
    }

    #[test]
    fn winemu_env_route_is_present() {
        let table = build_route_table();
        let resolved = table
            .resolve("/winemu/ui/env_setting/WinEmuEnvSettingActivity")
            .expect("winemu env setting route must be registered");
        assert_eq!(
            resolved.target(),
            "com.xj.winemu.ui.env_setting.WinEmuEnvSettingActivity"
        );
    }
}
